<style>
.bs-about{background:#f7f8fb;min-height:70vh;padding:56px 5% 78px;font-family:Inter,system-ui,sans-serif;color:#172033}.bs-wrap{max-width:1240px;margin:auto}.bs-hero{background:linear-gradient(135deg,#5b54ea,#8d82ff);border-radius:26px;padding:52px;color:#fff;display:grid;grid-template-columns:1.35fr .65fr;gap:30px;align-items:center;box-shadow:0 18px 45px rgba(91,84,234,.18)}.bs-hero h1{font-size:44px;line-height:1.05;margin:10px 0 15px}.bs-hero p{max-width:650px;color:#eeecff;line-height:1.8;font-size:14px}.bs-pill{display:inline-flex;padding:8px 11px;border-radius:999px;background:rgba(255,255,255,.1);border:1px solid rgba(255,255,255,.18);font-size:10px;font-weight:850;letter-spacing:.12em}.bs-illus{height:250px;border-radius:22px;background:rgba(255,255,255,.11);display:grid;place-items:center}.books-stack{position:relative;width:180px;height:140px}.books-stack span{position:absolute;left:10px;right:10px;height:38px;border-radius:7px;box-shadow:0 9px 20px rgba(0,0,0,.13)}.books-stack span:nth-child(1){bottom:0;background:#f7f3e6;transform:rotate(-4deg)}.books-stack span:nth-child(2){bottom:32px;background:#ffd3a4;transform:rotate(4deg)}.books-stack span:nth-child(3){bottom:64px;background:#c8d8ff;transform:rotate(-2deg)}.bs-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin-top:24px}.bs-card{background:#fff;border:1px solid #e8eaf0;border-radius:18px;padding:23px;box-shadow:0 10px 30px rgba(25,32,50,.04)}.bs-card i{color:#5b54ea;font-size:25px}.bs-card h3{margin:12px 0 7px;font-size:16px}.bs-card p{margin:0;color:#768092;font-size:13px;line-height:1.75}@media(max-width:800px){.bs-hero{grid-template-columns:1fr}.bs-hero h1{font-size:34px}.bs-grid{grid-template-columns:1fr}}
